import {listExpenses,saveExpense} from './local-db.mjs';
import {expenseRecord,expenseCategories,expenseTotals,expenseCSV} from './expenses-domain.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const format=(minor,currency)=>new Intl.NumberFormat('es-MX',{style:'currency',currency}).format(minor/100);
let rows=[],editing=null,ready=false;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
$('#categories').innerHTML=expenseCategories.map(c=>`<option>${c}</option>`).join('');$('#expense-form').elements.date.value=today();$('#month-filter').value=today().slice(0,7);$('#save').disabled=true;
const initialScope=new URLSearchParams(location.search).get('scope');if(['company','shopping'].includes(initialScope)){$('#expense-form').elements.scope.value=initialScope;$('#scope-filter').value=initialScope;}
function message(text,error=false){$('#message').className=error?'error':'callout';$('#message').textContent=text;}
function filtered(){return rows.filter(r=>($('#scope-filter').value==='all'||r.scope===$('#scope-filter').value)&&(!$('#month-filter').value||r.date.startsWith($('#month-filter').value))).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));}
function render(){const shown=filtered(),totals=expenseTotals(shown);$('#totals').innerHTML=Object.entries(totals).map(([currency,total])=>`<div class="key-value"><span>${currency}</span><strong>${format(total,currency)}</strong></div>`).join('')||'<p class="muted" style="margin-top:15px">Aún no hay gastos en este filtro.</p>';$('#records').innerHTML=shown.map(r=>`<tr><td><div class="row-title">${esc(r.title)}</div><div class="row-sub">${esc(r.date)} · ${esc(r.merchant)} · ${esc(r.category)}</div></td><td>${r.scope==='company'?'Empresa':'Personal'}</td><td>${format(r.amountMinor,r.currency)} ${r.currency}</td><td>${esc(r.reference)||'Sin referencia'}</td><td><button class="btn small outline" data-edit="${esc(r.id)}">Editar</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Registra tu primer gasto para comenzar.</td></tr>';document.querySelectorAll('[data-edit]').forEach(button=>button.onclick=()=>{editing=rows.find(r=>r.id===button.dataset.edit);const form=$('#expense-form');for(const name of ['scope','title','merchant','category','date','currency','reference'])form.elements[name].value=editing[name];form.elements.amount.value=(editing.amountMinor/100).toFixed(2);$('#form-title').textContent='Editar gasto';$('#cancel-edit').hidden=false;form.scrollIntoView({block:'start'});});}
function reset(){editing=null;$('#expense-form').reset();$('#expense-form').elements.date.value=today();$('#form-title').textContent='Registrar gasto';$('#cancel-edit').hidden=true;}
$('#expense-form').onsubmit=async e=>{e.preventDefault();if(!ready)return;$('#save').disabled=true;try{const record=expenseRecord(Object.fromEntries(new FormData(e.target)),editing);await saveExpense(record);rows=await listExpenses();reset();render();message('Gasto guardado en la base de datos local.');}catch(error){message(error.message,true);}finally{$('#save').disabled=!ready;}};
$('#cancel-edit').onclick=reset;$('#scope-filter').onchange=render;$('#month-filter').onchange=render;$('#all-dates').onclick=()=>{$('#month-filter').value='';render();};$('#export').onclick=()=>{const shown=filtered();if(!shown.length){message('No hay registros para exportar.');return;}const url=URL.createObjectURL(new Blob(['\ufeff'+expenseCSV(shown)],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='reap-gastos.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{rows=await listExpenses();ready=true;$('#save').disabled=false;$('#db-state').textContent='Base local lista. Los datos se conservan al cerrar y volver a abrir este navegador.';render();}catch(error){$('#db-state').textContent='Base local no disponible. No se guardarán gastos.';message(error.message,true);}
